    lines = ["def _raw(x):", "    s = %r" % model["baseline"]]

    def node(tree, i, depth):
        pad = "    " * depth
        if tree["is_leaf"][i]:
            return [pad + "s += %r" % tree["value"][i]]
        return ([pad + "if x[%d] <= %r:" % (tree["feature_idx"][i], tree["num_threshold"][i])]
                + node(tree, tree["left"][i], depth + 1)
                + [pad + "else:"]
                + node(tree, tree["right"][i], depth + 1))

    for tree in model["trees"]:
        lines += node(tree, 0, 1)
    lines.append("    return s")
    ns = {}
    exec(compile("\n".join(lines), "edgelens_nba_trees", "exec"), ns)
    return ns["_raw"]


def _isotonic(p):
    xs, ys = MODEL["iso_x"], MODEL["iso_y"]
    if p <= xs[0]:
        return ys[0]
    if p >= xs[-1]:
        return ys[-1]
