    while hi - lo > 1:
        mid = (lo + hi) // 2
        if xs[mid] <= p:
            lo = mid
        else:
            hi = mid
    x0, x1 = xs[lo], xs[hi]
    return ys[hi] if x1 == x0 else ys[lo] + (ys[hi] - ys[lo]) * (p - x0) / (x1 - x0)


