"""NHL live win probability (Poisson goals, market-implied strength).

Markets: NHL GAME (who wins).
Idea: before puck drop, read how strong the market thinks each team is from the pre-game price.
Once the game is on, re-price from the score and clock assuming goals arrive as a Poisson process
(about 6.1 goals per 60 minutes, split by that strength). A tie after regulation goes to OT/shootout.
Trades the default way: 1 contract when the edge after fees is at least min_edge, once per market.
"""
import math

GOALS_PER_60 = 6.1
_strength = {}  # game id -> home share of scoring, learned from the first pre-game price


def _pois(lam, kmax=15):
    out, p = [], math.exp(-lam)
    for k in range(kmax + 1):
        out.append(p)
        p *= lam / (k + 1)
    return out


def home_win_prob(share, diff, minutes_left):
    """P(home wins) given home share of goals, current home-minus-away diff, regulation minutes left."""
    lam = GOALS_PER_60 * max(minutes_left, 0) / 60
    ph, pa = _pois(lam * share), _pois(lam * (1 - share))
    win = tie = 0.0
    for h, x in enumerate(ph):
        for a, y in enumerate(pa):
            d = diff + h - a
            if d > 0:
                win += x * y
            elif d == 0:
                tie += x * y
    ot_home = 0.5 + (share - 0.5) * 0.5  # OT/shootout is closer to a coin flip
    return win + tie * ot_home


def _share_from_price(p_home):
    lo, hi = 0.2, 0.8
    for _ in range(40):
        mid = (lo + hi) / 2
        if home_win_prob(mid, 0, 60) < p_home:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def minutes_left(state):
    if not state:
        return 60.0
    period, clock = state.get("period") or 1, state.get("clock_s")
    if clock is None:
        clock = 1200
    if period > 3:
        return 0.0
    return ((3 - period) * 1200 + clock) / 60


def predict(market):
    if market["type"] != "GAME":
        return None
    yes_home = market["subject"] == market["game"]["home"]
    gid = market["game"]["id"]
    state = market.get("state") or {}
    status = state.get("status")
    bid, ask = market["yes_bid"], market["yes_ask"]
    if gid not in _strength:
        if status not in (None, "FUT", "PRE") or bid is None or ask is None:
            return None  # never saw a pre-game price for this game
        mid = (bid + ask) / 2
        _strength[gid] = _share_from_price(mid if yes_home else 1 - mid)
    share = _strength[gid]
    diff = (state.get("home_score") or 0) - (state.get("away_score") or 0)
    p_home = home_win_prob(share, diff, minutes_left(state))
    return p_home if yes_home else 1 - p_home

