"""NBA player points (pace vs. market prior).

Markets: NBA PTS ("player scores k+ points"). The first price the model sees for each line tells
it what the market expected; from that it backs out the player's expected points. During the game
it adds the points already scored to the expected points for the time left (scaled by game clock),
with a normal approximation. Edge appears when the market is slow to react to a scoring burst.
"""
import math

GAME_MINUTES = 48
_mu = {}  # (game, player) -> pre-game expected points


def _cdf(x):
    return 0.5 * (1 + math.erf(x / math.sqrt(2)))


def _ppf(p):
    lo, hi = -6.0, 6.0
    for _ in range(60):
        m = (lo + hi) / 2
        if _cdf(m) < p:
            lo = m
        else:
            hi = m
    return (lo + hi) / 2


def _sigma(mu):
    return max(2.5, 0.38 * mu + 1.5)


def elapsed_fraction(state):
    if not state or state.get("status") in (None, "PRE"):
        return 0.0
    period, clock = state.get("period") or 1, state.get("clock_s") or 0
    if period > 4:
        return 1.0
    return min(1.0, ((period - 1) * 720 + (720 - clock)) / (GAME_MINUTES * 60))


def predict(market):
    if market["type"] != "PTS" or market["line"] is None:
        return None
    bid, ask = market["yes_bid"], market["yes_ask"]
    key = (market["game"]["id"], market["subject"])
    frac = elapsed_fraction(market.get("state"))
    pts = market.get("player_points") or 0
    if key not in _mu:
        if bid is None or ask is None or frac > 0.1:
            return None
        mid = min(max((bid + ask) / 2, 0.03), 0.97)
        # find mu with P(X >= line) = mid, X ~ N(mu, sigma(mu)), continuity-corrected
        lo, hi = 0.0, 60.0
        for _ in range(50):
            mu = (lo + hi) / 2
            p = 1 - _cdf((market["line"] - 0.5 - pts - mu * (1 - frac)) / _sigma(mu))
            if p < mid:
                lo = mu
            else:
                hi = mu
        _mu[key] = (lo + hi) / 2
    mu = _mu[key]
    left = max(1 - frac, 0.0)
    need = market["line"] - pts
    if need <= 0:
        return 1.0
    if left == 0:
        return 0.0
    sd = _sigma(mu) * math.sqrt(left)
    return 1 - _cdf((need - 0.5 - mu * left) / sd)

"""NHL live win probability with quarter-Kelly sizing.

Same pricing as "NHL live win probability", but decide() sizes each bet with a quarter of the
Kelly fraction of current cash, so bigger edges get more contracts (up to the depth at the ask).
Shows how a model controls its own size. Adds to a position at most 3 times per market.
"""
import math

GOALS_PER_60 = 6.1
KELLY_FRACTION = 0.25
MIN_EDGE = 0.03
MAX_ENTRIES = 3
_strength = {}
_entries = {}


def _pois(lam, kmax=15):
    out, p = [], math.exp(-lam)
    for k in range(kmax + 1):
        out.append(p)
        p *= lam / (k + 1)
    return out


def home_win_prob(share, diff, minutes_left):
    lam = GOALS_PER_60 * max(minutes_left, 0) / 60
    ph, pa = _pois(lam * share), _pois(lam * (1 - share))
    win = tie = 0.0
    for h, x in enumerate(ph):
        for a, y in enumerate(pa):
            d = diff + h - a
            if d > 0:
                win += x * y
            elif d == 0:
                tie += x * y
    return win + tie * (0.5 + (share - 0.5) * 0.5)


def _share_from_price(p_home):
    lo, hi = 0.2, 0.8
    for _ in range(40):
        mid = (lo + hi) / 2
        if home_win_prob(mid, 0, 60) < p_home:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def predict(market):
    if market["type"] != "GAME":
        return None
    yes_home = market["subject"] == market["game"]["home"]
    gid = market["game"]["id"]
    state = market.get("state") or {}
    bid, ask = market["yes_bid"], market["yes_ask"]
    if gid not in _strength:
        if state.get("status") not in (None, "FUT", "PRE") or bid is None or ask is None:
            return None
        mid = (bid + ask) / 2
        _strength[gid] = _share_from_price(mid if yes_home else 1 - mid)
    period, clock = state.get("period") or 1, state.get("clock_s")
    clock = 1200 if clock is None else clock
    mins = 0.0 if period > 3 else ((3 - period) * 1200 + clock) / 60
    diff = (state.get("home_score") or 0) - (state.get("away_score") or 0)
    p_home = home_win_prob(_strength[gid], diff, mins)
    return p_home if yes_home else 1 - p_home


def _fee_per_contract(price):
    return 0.07 * price * (1 - price) + 0.005


def decide(market, prob):
    if _entries.get(market["ticker"], 0) >= MAX_ENTRIES:
        return None
    best = None
    for side, price, p in (("yes", market["yes_ask"], prob), ("no", market["no_ask"], 1 - prob)):
        if price is None or not 0.02 <= price <= 0.98:
            continue
        cost = price + _fee_per_contract(price)
        edge = p - cost
        if edge >= MIN_EDGE and (best is None or edge > best[1]):
            best = (side, edge, cost, p)
    if not best:
        return None
    side, edge, cost, p = best
    b = (1 - cost) / cost              # net odds per $1 staked
    kelly = (p * b - (1 - p)) / b      # Kelly fraction of bankroll
    stake = max(0.0, kelly * KELLY_FRACTION) * market["cash"]
    contracts = int(stake / cost)
    if contracts < 1:
        return None
    _entries[market["ticker"]] = _entries.get(market["ticker"], 0) + 1
    return {"side": side, "contracts": contracts}
